<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('communication','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM customer_chats WHERE tenant_id=? ORDER BY COALESCE(last_message_at,created_at) DESC LIMIT 200");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Customer Chat';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Customer Chat</h2><p>Support conversations and customer service queue.</p></div></div><div class="table-responsive"><table><thead><tr><th>Customer</th><th>Channel</th><th>Subject</th><th>Status</th><th>Last Message</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['customer_id']??'—')?></td><td><?=e($x['channel'])?></td><td><?=e($x['subject']??'—')?></td><td><?=e($x['status'])?></td><td><?=e($x['last_message_at']??$x['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No customer conversations yet.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>